50		init_pair(CP_HOSTILE, COLOR_RED, bg);
51		init_pair(CP_BASE, COLOR_CYAN, bg);
52		init_pair(CP_STAR, COLOR_BLUE, bg);
53		init_pair(CP_PLANET, COLOR_GREEN, bg);
54		init_pair(CP_THING, COLOR_MAGENTA, bg);
