/* Put the unfinished line back if the resize took it away. A
   growth keeps it and needs nothing; a shrink usually clips it,
   and a prompt silently gone reads as a game that has stopped.
   Which happened is answered by reading the row the cursor is on
   and looking for the line there. */
if (curlen > 0) {
	char onscreen[sizeof curline];
	int y, x;

	getyx(wmsg, y, x);
	onscreen[0] = '\0';
	mvwinnstr(wmsg, y, 0, onscreen, (int)sizeof onscreen - 1);
